$_SESSION['admin_csrf']??=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals($_SESSION['admin_csrf'],(string)($_POST['_token']??'')))throw new RuntimeException('Session expired. Please try again.');
  $action=(string)($_POST['action']??'');
  if($action==='account_status'){$uid=(int)($_POST['user_id']??0);$status=(string)($_POST['account_status']??'');if($uid<1||!in_array($status,['active','suspended'],true))throw new RuntimeException('Invalid account update.');if($uid===(int)$_SESSION['account']['id']&&$status==='suspended')throw new RuntimeException('You cannot suspend your own administrator account.');$q=$pdo->prepare("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=:uid AND r.code='admin'");$q->execute(['uid'=>$uid]);if($q->fetchColumn())throw new RuntimeException('Admin accounts are protected from suspension here.');$q=$pdo->prepare('UPDATE users SET account_status=:s WHERE id=:uid');$q->execute(['s'=>$status,'uid'=>$uid]);$_SESSION['admin_notice']='Account updated.';}
  elseif($action==='grant_role'){$uid=(int)($_POST['user_id']??0);$assignment=explode(':',(string)($_POST['assignment']??''));$pid=(int)($assignment[0]??0);$rid=(int)($assignment[1]??0);if($uid<1||$pid<1||$rid<1)throw new RuntimeException('Choose a valid role to grant.');$q=$pdo->prepare("INSERT INTO user_pillar_roles(user_id,pillar_id,role_id,status) VALUES(:uid,:pid,:rid,'active') ON CONFLICT(user_id,pillar_id,role_id) DO UPDATE SET status='active',updated_at=NOW()");$q->execute(['uid'=>$uid,'pid'=>$pid,'rid'=>$rid]);$_SESSION['admin_notice']='Role access enabled.';}
  elseif($action==='role_status'){$uid=(int)($_POST['user_id']??0);$status=(string)($_POST['role_status']??'');if($uid<1||!in_array($status,['pending','active','disabled','suspended'],true))throw new RuntimeException('Invalid role update.');$q=$pdo->prepare('UPDATE user_pillar_roles SET status=:s,updated_at=NOW() WHERE user_id=:uid AND pillar_id=:pid AND role_id=:rid');$q->execute(['s'=>$status,'uid'=>$uid,'pid'=>(int)($_POST['pillar_id']??0),'rid'=>(int)($_POST['role_id']??0)]);$_SESSION['admin_notice']='Pillar role updated.';}
  elseif($action==='order_status'){$id=(int)($_POST['order_id']??0);$status=(string)($_POST['status']??'');if($id<1||!in_array($status,['pending','paid','processing','fulfilled','cancelled','refunded'],true))throw new RuntimeException('Choose a valid order status.');$q=$pdo->prepare('UPDATE orders SET status=:status,updated_at=NOW() WHERE id=:id');$q->execute(['status'=>$status,'id'=>$id]);$_SESSION['admin_notice']='Order status updated.';}
  elseif($action==='booking_status'){$id=(int)($_POST['booking_id']??0);$status=(string)($_POST['status']??'');if($id<1||!in_array($status,['requested','confirmed','declined','cancelled','completed'],true))throw new RuntimeException('Choose a valid booking status.');$q=$pdo->prepare('UPDATE bookings SET status=:status WHERE id=:id');$q->execute(['status'=>$status,'id'=>$id]);$_SESSION['admin_notice']='Booking status updated.';}
  elseif($action==='listing_status'){$id=trim((string)($_POST['listing_id']??''));$status=(string)($_POST['status']??'');if($id===''||!in_array($status,['draft','published','archived'],true))throw new RuntimeException('Choose a valid listing status.');$q=$pdo->prepare('UPDATE listings SET status=:s WHERE id=:id');$q->execute(['s'=>$status,'id'=>$id]);$_SESSION['admin_notice']='Listing status saved.';}
  elseif($action==='update_listing'){$id=trim((string)($_POST['listing_id']??''));$title=trim((string)($_POST['title']??''));$provider=trim((string)($_POST['provider_name']??''));$location=trim((string)($_POST['location']??''));$description=trim((string)($_POST['description']??''));$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$unit=trim((string)($_POST['price_unit']??''));$image=trim((string)($_POST['image_url']??''));if($id===''||$title===''||$provider===''||$location===''||$price===false||$price<0||$unit==='')throw new RuntimeException('Complete listing details with valid values.');$q=$pdo->prepare('UPDATE listings SET title=:title,provider_name=:provider,location=:location,description=:description,price_minor=:price,price_unit=:unit,emoji=:image WHERE id=:id');$q->execute(['title'=>$title,'provider'=>$provider,'location'=>$location,'description'=>$description,'price'=>(int)round($price*100),'unit'=>$unit,'image'=>$image,'id'=>$id]);$_SESSION['admin_notice']='Listing details updated.';}
  elseif($action==='create_listing'){$title=trim((string)($_POST['title']??''));$provider=trim((string)($_POST['provider_name']??''));$pillar=(string)($_POST['pillar']??'');$type=(string)($_POST['item_type']??'');$location=trim((string)($_POST['location']??''));$desc=trim((string)($_POST['description']??''));$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$unit=trim((string)($_POST['price_unit']??''));$emoji=trim((string)($_POST['emoji']??''));if($title===''||$provider===''||$location===''||!in_array($pillar,['Agri-Fishery','Tourism','Education'],true)||!in_array($type,['Product','Experience','Course'],true)||$price===false||$price<0||$unit==='')throw new RuntimeException('Complete required listing fields with valid values.');$id='admin-'.bin2hex(random_bytes(6));$q=$pdo->prepare("INSERT INTO listings(id,provider_name,pillar,item_type,title,description,price_minor,price_unit,location,emoji,badge,status,featured) VALUES(:id,:provider,:pillar,:type,:title,:description,:price,:unit,:location,:emoji,'New listing','published',FALSE)");$q->execute(['id'=>$id,'provider'=>$provider,'pillar'=>$pillar,'type'=>$type,'title'=>$title,'description'=>$desc,'price'=>(int)round($price*100),'unit'=>$unit,'location'=>$location,'emoji'=>$emoji]);$_SESSION['admin_notice']='Listing created and published.';}
  else throw new RuntimeException('Unknown admin action.');
 }catch(Throwable $e){$_SESSION['admin_notice']=$e instanceof PDOException?'The update could not be saved. Check the database schema and try again.':$e->getMessage();}
