}
$notice=$_SESSION['admin_notice']??'';unset($_SESSION['admin_notice']);$search=trim((string)($_GET['q']??''));$stats=$pdo->query("SELECT COUNT(*) total,COUNT(*) FILTER(WHERE account_status='active') active,COUNT(*) FILTER(WHERE account_status='suspended') suspended FROM users")->fetch();$pending=(int)$pdo->query("SELECT COUNT(*) FROM user_pillar_roles WHERE status='pending'")->fetchColumn();
$sql="SELECT u.id user_id,u.name,u.email,u.account_status,u.created_at,p.id pillar_id,p.name pillar,r.id role_id,r.name role_name,upr.status role_status FROM users u LEFT JOIN user_pillar_roles upr ON upr.user_id=u.id LEFT JOIN pillars p ON p.id=upr.pillar_id LEFT JOIN roles r ON r.id=upr.role_id";if($search!=='')$sql.=' WHERE u.name ILIKE :q1 OR u.email ILIKE :q2';$sql.=' ORDER BY u.created_at DESC,p.sort_order,r.sort_order LIMIT 500';$q=$pdo->prepare($sql);if($search!==''){$q->bindValue(':q1','%'.$search.'%');$q->bindValue(':q2','%'.$search.'%');}$q->execute();$users=[];foreach($q->fetchAll() as $row){$id=(int)$row['user_id'];$users[$id]??=['id'=>$id,'name'=>$row['name'],'email'=>$row['email'],'account_status'=>$row['account_status'],'created_at'=>$row['created_at'],'roles'=>[]];if($row['role_id'])$users[$id]['roles'][]=$row;}$allListings=$pdo->query('SELECT id,title,provider_name,pillar,item_type,description,emoji,price_minor,price_unit,location,status FROM listings ORDER BY created_at DESC LIMIT 500')->fetchAll();$ordersList=$pdo->query('SELECT o.id,o.status,o.subtotal_minor,o.currency,o.created_at,u.name,u.email,COUNT(oi.id) item_count FROM orders o LEFT JOIN users u ON u.id=o.customer_user_id LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id,u.name,u.email ORDER BY o.created_at DESC LIMIT 250')->fetchAll();$bookingsList=$pdo->query('SELECT b.id,b.status,b.requested_for,b.guest_count,b.created_at,l.title,l.provider_name,u.name guest_name,u.email FROM bookings b JOIN listings l ON l.id=b.listing_id LEFT JOIN users u ON u.id=b.customer_user_id ORDER BY b.created_at DESC LIMIT 250')->fetchAll();$roleCatalog=account_role_catalog($pdo);$listingStats=['total'=>count($allListings),'published'=>0,'draft'=>0];foreach($allListings as $l){if($l['status']==='published')$listingStats['published']++;if($l['status']==='draft')$listingStats['draft']++;}
